const ExcelJS = require('exceljs');
async function run() {
  const workbook = new ExcelJS.Workbook();
  const filePath = 'C:\\\\Users\\\\lg\\\\Desktop\\\\오늘\\\\(데이터검증팀)실사 DB 취합_전달용_260720_배현명.xlsx';
  await workbook.xlsx.readFile(filePath);
  const sheet = workbook.getWorksheet('기업 정보');

  let firstRow = null;
  let lastRow = null;
  let count = 0;

  for (let r = 2; r <= 25000; r++) {
    const row = sheet.getRow(r);
    const author = String(row.getCell(1).value || '').trim();
    if (author === '배현명') {
      if (firstRow === null) firstRow = r;
      lastRow = r;
      count++;
    }
  }

  console.log('배현명 row range:', firstRow, 'to', lastRow, 'total:', count);

  // Inspect the first 5 and last 5 rows of 배현명
  console.log('First 배현명 row (Row ' + firstRow + '):', sheet.getRow(firstRow).values.slice(1, 15));
  console.log('Last 배현명 row (Row ' + lastRow + '):', sheet.getRow(lastRow).values.slice(1, 15));
}
run().catch(console.error);
